// adds the ambient light to a light intensity, clamped to 1 (the float bits compared as ints)
#define FAST_AMBIENT_LIGHT_ADDITION(p) \
	do \
	{ \
		if (*(int *)(p) < 0) \
		{ \
			*(p) = ambient_light_level; \
		} \
		else \
		{ \
			*(p) = ambient_light_level + *(p); \
			if (*(int *)(p) > 0x3F800000) \
				*(p) = 1.0f; \
		} \
	} while (0)

